  ('2f847854-9f50-5c9c-9c33-8c70aa951210', '96d3f4ef-dd23-5501-bff5-e4d27b6420a0', 'company', 'Milano Atelier S.r.l.', 'Italia', 'Milano', 'Giulia Bianchi', '+39 02 5551 2201', 'owner@milanoatelier.demo', 'milano_atelier_demo', '/images/placeholder/wechat-qr-milano-atelier.svg', ARRAY['niche-jewelry', 'fashion-accessories', 'home-design']::text[], '米兰独立买手工作室，主营小众设计师饰品与家居选品。', ARRAY['/images/placeholder/docs/milano-atelier-company-cert.pdf']::text[], '长期合作 6 家米兰本地设计师工作室，可实地验货。', 'Milano, Italia', '签收后 7 天内可协商退换。', true, 'approved', '0165b799-5bf7-53a1-99e1-70a7e943d741', '资料齐全，企业资质已核实', '2026-05-04T09:00:00+02:00', '2026-04-28T09:00:00+02:00', '2026-05-04T09:00:00+02:00'),
  ('d63a3bc9-a229-5b4b-a30d-ff20c8438d3c', '96d3f4ef-dd23-5501-bff5-e4d27b6420a0', 'company', 'Torino Objects S.r.l.', 'Italia', 'Torino', 'Luca Ferrero', '+39 011 555 3302', 'owner@torinoobjects.demo', 'torino_objects_demo', '/images/placeholder/wechat-qr-torino-objects.svg', ARRAY['home-design', 'collectible-figures']::text[], '都灵设计器物集合店。', ARRAY['/images/placeholder/docs/torino-objects-company-cert.pdf']::text[], '自有设计工作室与本地铸造厂合作。', 'Torino, Italia', '发货前拍照确认，运输破损可协商处理。', true, 'approved', '0165b799-5bf7-53a1-99e1-70a7e943d741', '通过审核', '2026-05-11T09:00:00+02:00', '2026-05-06T09:00:00+02:00', '2026-05-11T09:00:00+02:00'),
  ('90445f35-d468-59d7-8188-d532fb59fc0b', '96d3f4ef-dd23-5501-bff5-e4d27b6420a0', 'company', 'Firenze Piccoli Collettivo S.r.l.', 'Italia', 'Firenze', 'Elena Romano', '+39 055 555 4403', 'owner@firenzecraft.demo', 'firenze_craft_demo', '/images/placeholder/wechat-qr-firenze-craft.svg', ARRAY['italian-crafts', 'fragrance-lifestyle']::text[], '联合佛罗伦萨多家传统手工作坊的选品平台。', ARRAY['/images/placeholder/docs/firenze-craft-company-cert.pdf']::text[], '联合 12 家本地手工作坊。', 'Firenze, Italia', '手工制品天然材质差异属正常现象。', true, 'approved', '0165b799-5bf7-53a1-99e1-70a7e943d741', '通过审核，本地认证已核实', '2026-04-19T09:00:00+02:00', '2026-04-15T09:00:00+02:00', '2026-04-19T09:00:00+02:00'),
  ('b4a5ecfc-ee87-523a-895c-098e5f5e1f8b', '5ce4d324-9eb8-5299-8b77-f9c1b8956916', 'individual', 'Marco Rossi', 'Italia', 'Modena', 'Marco Rossi', '+39 059 555 5504', 'owner@modenacollectors.demo', 'modena_collectors_demo', '/images/placeholder/wechat-qr-modena-collectors.svg', ARRAY['ferrari-car-models', 'limited-editions']::text[], '专注法拉利与经典赛车限量模型的资深藏家买手。', ARRAY['/images/placeholder/docs/marco-rossi-id.pdf']::text[], '本地藏家网络与官方授权经销商渠道。', 'Modena, Italia', '发货前提供开箱验货视频。', true, 'approved', '0165b799-5bf7-53a1-99e1-70a7e943d741', '通过审核，个人资质已核实', '2026-03-14T09:00:00+02:00', '2026-03-10T09:00:00+02:00', '2026-03-14T09:00:00+02:00'),
  ('e0a9413c-a08e-5075-a5fd-c8e64e70c59b', '96d3f4ef-dd23-5501-bff5-e4d27b6420a0', 'individual', 'Chiara Colombo', 'Italia', 'Milano', 'Chiara Colombo', '+39 345 555 6605', 'owner@chiarabuyer.demo', 'chiara_milano_demo', '/images/placeholder/wechat-qr-chiara.svg', ARRAY['fashion-accessories', 'niche-jewelry', 'other-italian-goods']::text[], '常驻米兰的独立买手，熟悉本地小众品牌与折扣村资源。', ARRAY['/images/placeholder/docs/chiara-colombo-id.pdf']::text[], '本地折扣村与设计师工作室长期合作。', 'Milano, Italia', '代购性质商品以协商为准，平台不提供担保交易。', false, 'approved', '0165b799-5bf7-53a1-99e1-70a7e943d741', '通过审核', '2026-05-31T09:00:00+02:00', '2026-05-26T09:00:00+02:00', '2026-05-31T09:00:00+02:00'),
  ('94ab7924-fb45-5c93-abd6-122f120a4f95', 'a1186d90-48f6-584c-86bf-e97b08434b52', 'individual', '陈曦', 'Italia', 'Bologna', '陈曦', '+86 138 0000 1002', 'chenxi.demo@example.com', 'chenxi_demo', NULL, ARRAY['fragrance-lifestyle', 'other-italian-goods']::text[], '计划从博洛尼亚周边发掘小众生活方式好物，首次申请入驻。', ARRAY['/images/placeholder/docs/chenxi-id-draft.pdf']::text[], '本地留学生资源，尚在积累供应链中。', 'Bologna, Italia', '尚未提供，等待补充资料。', true, 'needs_more_info', '0165b799-5bf7-53a1-99e1-70a7e943d741', '请补充采购能力证明与更清晰的售后规则说明', '2026-07-15T09:00:00+02:00', '2026-07-10T09:00:00+02:00', '2026-07-15T09:00:00+02:00')
